import unittest
from batching import batches

class BatchTests(unittest.TestCase):
    def test_list(self):
        self.assertEqual(batches([1,2,3], 2), [[1,2],[3]])
    def test_size(self):
        with self.assertRaises(ValueError):
            batches([1], 0)

if __name__ == '__main__':
    unittest.main()

